// Tiny tamagotchi-style pet for Arduino Uno.
// OLED SSD1306 (I2C A4/A5) shows the face, three buttons (D2 feed, D3 play, D4 stats)
// to GND with INPUT_PULLUP, active buzzer on D8 chirps.
// Stats: hunger and happiness, 0..100 where 100 = full / very happy. Both drop over time.
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

const uint8_t PIN_FEED = 2, PIN_PLAY = 3, PIN_STATS = 4, PIN_BUZZ = 8;

// Tunables (shortened for demo; raise DECAY_MS for a slower pet)
const unsigned long DECAY_MS = 5000;     // one decay tick every 5 s
const uint8_t HUNGER_DECAY = 2;          // hunger lost per tick
const uint8_t HAPPY_DECAY = 1;           // happiness lost per tick
const uint8_t FEED_AMOUNT = 20;
const uint8_t PLAY_AMOUNT = 15;
const uint8_t PLAY_HUNGER_COST = 5;      // playing makes it hungry
const uint8_t ALERT_LEVEL = 20;          // warning chirp when a stat drops below this
const unsigned long STATS_SHOW_MS = 4000;
const unsigned long DEBOUNCE_MS = 30;

Adafruit_SSD1306 display(128, 64, &Wire, -1);
bool haveDisplay = false;

uint8_t hunger = 80, happy = 80;
unsigned long lastDecay = 0;
bool statsMode = false;
unsigned long statsUntil = 0;
bool dirty = true;
bool hungryAlerted = false, sadAlerted = false;

// ---------- buttons (debounced, falling-edge) ----------
struct Button { uint8_t pin; bool stable; bool lastRaw; unsigned long changedAt; };
Button buttons[3] = { {PIN_FEED, HIGH, HIGH, 0}, {PIN_PLAY, HIGH, HIGH, 0}, {PIN_STATS, HIGH, HIGH, 0} };

bool pressed(Button &b, unsigned long now) {
  bool raw = digitalRead(b.pin);
  if (raw != b.lastRaw) { b.lastRaw = raw; b.changedAt = now; }
  if (now - b.changedAt >= DEBOUNCE_MS && raw != b.stable) {
    b.stable = raw;
    return raw == LOW;   // pressed = pulled to GND
  }
  return false;
}

// ---------- non-blocking buzzer patterns ----------
// Pattern: on/off durations in ms, terminated by 0. Even index = on, odd = off.
const uint16_t CHIRP_FEED[]  = {60, 40, 60, 0};
const uint16_t CHIRP_PLAY[]  = {40, 30, 40, 30, 80, 0};
const uint16_t CHIRP_STATS[] = {30, 0};
const uint16_t CHIRP_ALERT[] = {200, 100, 200, 100, 200, 0};
const uint16_t *chirpPat = nullptr;
uint8_t chirpIdx = 0;
unsigned long chirpStepAt = 0;

void chirp(const uint16_t *pat, const __FlashStringHelper *name) {
  chirpPat = pat; chirpIdx = 0; chirpStepAt = millis();
  digitalWrite(PIN_BUZZ, HIGH);
  Serial.print(F("chirp ")); Serial.println(name);
}

void updateChirp(unsigned long now) {
  if (!chirpPat) return;
  if (now - chirpStepAt >= chirpPat[chirpIdx]) {
    chirpStepAt = now;
    chirpIdx++;
    if (chirpPat[chirpIdx] == 0) { chirpPat = nullptr; digitalWrite(PIN_BUZZ, LOW); return; }
    digitalWrite(PIN_BUZZ, (chirpIdx % 2 == 0) ? HIGH : LOW);
  }
}

// ---------- mood ----------
enum Mood { HAPPY, OK, SAD };
Mood mood() {
  uint8_t low = hunger < happy ? hunger : happy;
  if (low >= 60) return HAPPY;
  if (low >= 30) return OK;
  return SAD;
}
const __FlashStringHelper *moodName(Mood m) {
  return m == HAPPY ? F("happy") : m == OK ? F("ok") : F("sad");
}
Mood lastMood;

void printStats(const __FlashStringHelper *event) {
  Serial.print(event);
  Serial.print(F(" hunger=")); Serial.print(hunger);
  Serial.print(F(" happy=")); Serial.print(happy);
  Serial.print(F(" mood=")); Serial.println(moodName(mood()));
}

// ---------- drawing ----------
void drawMouth(int cx, int cy, int curve) {  // curve>0 smile, <0 frown, 0 flat
  for (int dx = -14; dx <= 14; dx++) {
    int dy = (curve * (196 - dx * dx)) / 196;   // parabola, |dy| <= |curve| at centre
    display.drawPixel(cx + dx, cy + dy, SSD1306_WHITE);
    display.drawPixel(cx + dx, cy + dy + 1, SSD1306_WHITE);
  }
}

void drawFace() {
  Mood m = mood();
  display.drawCircle(64, 30, 26, SSD1306_WHITE);           // head
  if (m == SAD) {                                          // droopy eyes
    display.drawLine(48, 20, 58, 24, SSD1306_WHITE);
    display.drawLine(70, 24, 80, 20, SSD1306_WHITE);
    display.fillCircle(54, 27, 2, SSD1306_WHITE);
    display.fillCircle(74, 27, 2, SSD1306_WHITE);
  } else {
    display.fillCircle(54, 24, 4, SSD1306_WHITE);
    display.fillCircle(74, 24, 4, SSD1306_WHITE);
  }
  drawMouth(64, 40, m == HAPPY ? 6 : m == OK ? 0 : -6);
  display.setTextSize(1);
  display.setCursor(0, 0);  display.print(moodName(m));
  // tiny bars at the bottom: H left, J right
  display.setCursor(0, 57);  display.print('H');
  display.drawRect(8, 57, 52, 7, SSD1306_WHITE);
  display.fillRect(9, 58, hunger / 2, 5, SSD1306_WHITE);
  display.setCursor(66, 57); display.print('J');
  display.drawRect(74, 57, 52, 7, SSD1306_WHITE);
  display.fillRect(75, 58, happy / 2, 5, SSD1306_WHITE);
}

void drawBar(int y, const __FlashStringHelper *label, uint8_t v) {
  display.setCursor(0, y); display.print(label);
  display.setCursor(104, y); display.print(v);
  display.drawRect(0, y + 10, 128, 8, SSD1306_WHITE);
  display.fillRect(1, y + 11, (v * 126) / 100, 6, SSD1306_WHITE);
}

void drawStats() {
  display.setTextSize(1);
  drawBar(0, F("Hunger"), hunger);
  drawBar(24, F("Happiness"), happy);
  display.setCursor(0, 52); display.print(F("Mood: ")); display.print(moodName(mood()));
}

void render() {
  if (!haveDisplay) return;
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  if (statsMode) drawStats(); else drawFace();
  display.display();
}

// ---------- game logic ----------
void checkAlerts() {
  if (hunger < ALERT_LEVEL && !hungryAlerted) { hungryAlerted = true; Serial.println(F("alert hungry")); chirp(CHIRP_ALERT, F("alert")); }
  else if (happy < ALERT_LEVEL && !sadAlerted) { sadAlerted = true; Serial.println(F("alert lonely")); chirp(CHIRP_ALERT, F("alert")); }
  if (hunger >= ALERT_LEVEL) hungryAlerted = false;
  if (happy >= ALERT_LEVEL) sadAlerted = false;
}

void moodCheck() {
  Mood m = mood();
  if (m != lastMood) { lastMood = m; Serial.print(F("mood -> ")); Serial.println(moodName(m)); }
}

uint8_t addCap(uint8_t v, uint8_t a) { return (v + a > 100) ? 100 : v + a; }
uint8_t subFloor(uint8_t v, uint8_t a) { return v > a ? v - a : 0; }

void setup() {
  Serial.begin(115200);
  pinMode(PIN_FEED, INPUT_PULLUP);
  pinMode(PIN_PLAY, INPUT_PULLUP);
  pinMode(PIN_STATS, INPUT_PULLUP);
  pinMode(PIN_BUZZ, OUTPUT);
  digitalWrite(PIN_BUZZ, LOW);

  Wire.begin();
  Wire.beginTransmission(0x3C);
  haveDisplay = (Wire.endTransmission() == 0) && display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  if (!haveDisplay) Serial.println(F("SSD1306 not found at 0x3C: running without display"));
  else Serial.println(F("display ready"));

  lastMood = mood();
  lastDecay = millis();
  printStats(F("boot"));
  chirp(CHIRP_FEED, F("hello"));
  render();
}

void loop() {
  unsigned long now = millis();

  if (pressed(buttons[0], now)) {
    if (hunger >= 100) { printStats(F("feed refused (full)")); chirp(CHIRP_STATS, F("refuse")); }
    else { hunger = addCap(hunger, FEED_AMOUNT); printStats(F("feed")); chirp(CHIRP_FEED, F("feed")); }
    statsMode = false; dirty = true;
  }
  if (pressed(buttons[1], now)) {
    happy = addCap(happy, PLAY_AMOUNT);
    hunger = subFloor(hunger, PLAY_HUNGER_COST);
    printStats(F("play")); chirp(CHIRP_PLAY, F("play"));
    statsMode = false; dirty = true;
    checkAlerts();
  }
  if (pressed(buttons[2], now)) {
    statsMode = true; statsUntil = now + STATS_SHOW_MS;
    printStats(F("stats shown")); chirp(CHIRP_STATS, F("stats"));
    dirty = true;
  }
  if (statsMode && (long)(now - statsUntil) >= 0) {
    statsMode = false; dirty = true; Serial.println(F("stats hidden"));
  }

  if (now - lastDecay >= DECAY_MS) {
    lastDecay += DECAY_MS;
    hunger = subFloor(hunger, HUNGER_DECAY);
    happy = subFloor(happy, HAPPY_DECAY);
    printStats(F("tick"));
    checkAlerts();
    dirty = true;
  }

  moodCheck();
  updateChirp(now);
  if (dirty) { dirty = false; render(); }
}

